const root = $input.item.json || {};
const headers = root.headers || {};
const header = (name) => headers[name] || headers[name.toLowerCase()] || headers[name.toUpperCase()] || '';
const rawAuth = String(header('authorization') || '');
const bearer = rawAuth.toLowerCase().startsWith('bearer ') ? rawAuth.slice(7).trim() : '';
const provided = String(header('x-dunning-token') || bearer || '').trim();
const expected = String($vars.DUNNING_WEBHOOK_TOKEN || '').trim();
return { json: {
  ...root,
  auth_ok: Boolean(expected && provided && provided === expected),
  auth_reason: !expected ? 'missing_server_token_var' : !provided ? 'missing_token_header' : provided === expected ? '' : 'bad_token',
  checked_at: new Date().toISOString(),
} };

const crypto = require('crypto');
const PRICE_BOOK_VERSION = 'INVOICE_PRICE_BOOK_V1_2026-06-30';
const VAT_RATE = 0.23;
const FIRST_NUDGE_DAYS = 3;
const PRICE_BOOK = {
  automation_audit: { label: 'Automation audit and quick-win map', unit_net_pln: 2500, min_qty: 1, max_qty: 1 },
  workflow_build: { label: 'n8n workflow build', unit_net_pln: 3200, min_qty: 1, max_qty: 3 },
  ai_workshop: { label: 'AI operations workshop', unit_net_pln: 4500, min_qty: 1, max_qty: 2 },
  support_retainer: { label: 'Automation support retainer', unit_net_pln: 1800, min_qty: 1, max_qty: 6 },
};
const root = $input.item.json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const collapse = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const pick = (...keys) => {
  for (const key of keys) {
    const value = body[key];
    if (value !== undefined && value !== null && collapse(value) !== '') return collapse(value);
  }
  return '';
};
const htmlEscape = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}[ch]));
const money = (value) => Number(value || 0).toLocaleString('pl-PL', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const now = new Date();
const event_type = collapse(pick('event_type', 'type')).toLowerCase();
const statusText = collapse(pick('job_status', 'status')).toLowerCase();
const completionLike = ['job.completed', 'job_complete', 'job.complete', 'complete', 'completed'].includes(event_type) || statusText === 'complete' || statusText === 'completed';
const job_id = collapse(pick('job_id', 'jobId', 'work_order_id'));
const completion_event_id = collapse(pick('event_id', 'id', 'completion_event_id')) || crypto.createHash('sha256').update(JSON.stringify(body)).digest('hex').slice(0, 16);
const completed_at_raw = collapse(pick('completed_at', 'completedAt', 'completion_time')) || now.toISOString();
const completedDate = new Date(completed_at_raw);
const completed_at = Number.isNaN(completedDate.getTime()) ? now.toISOString() : completedDate.toISOString();
const client_name = collapse(pick('client_name', 'name', 'full_name')) || 'Unknown';
const company = collapse(pick('company', 'Company')) || 'Unknown';
const verified_email = collapse(pick('verified_email', 'email', 'client_email')).toLowerCase();
const service_code = collapse(pick('service_code', 'service')).toLowerCase();
const quantity = Number(pick('quantity', 'qty', 'units') || '1');
const hasOwn = (name) => Object.prototype.hasOwnProperty.call(body, name);
const onboarding_id_provided = hasOwn('onboarding_id');
const onboarding_id_value = body.onboarding_id;
const onboarding_id_valid = !onboarding_id_provided || (typeof onboarding_id_value === 'string' && /^[a-f0-9]{64}$/i.test(onboarding_id_value));
const onboarding_id = onboarding_id_valid && onboarding_id_provided ? onboarding_id_value.toLowerCase() : '';
const smoke_tag_provided = hasOwn('smoke_tag');
const smoke_tag_value = body.smoke_tag;
const smoke_tag_valid = !smoke_tag_provided || (typeof smoke_tag_value === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(smoke_tag_value));
const smoke_tag = smoke_tag_valid && smoke_tag_provided ? smoke_tag_value : '';
const rules = PRICE_BOOK[service_code];
const errors = [];
if (!completionLike) errors.push('event is not a job completion');
if (!job_id) errors.push('job_id missing');
if (!verified_email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(verified_email)) errors.push('verified_email invalid');
if (!service_code) errors.push('service_code missing');
if (!onboarding_id_valid) errors.push('onboarding_id must be exactly 64 hexadecimal characters when provided');
if (!smoke_tag_valid) errors.push('smoke_tag must match the bounded run-tag contract when provided');
if (!rules) errors.push('service_code not in price book');
if (!Number.isInteger(quantity)) errors.push('quantity must be an integer');
if (rules && Number.isInteger(quantity) && (quantity < rules.min_qty || quantity > rules.max_qty)) errors.push('quantity outside price-book bounds');
const valid_input = completionLike && errors.length === 0;
const invoice_key = job_id ? crypto.createHash('sha256').update('invoice.v1\n' + job_id, 'utf8').digest('hex') : '';
const dead_key = crypto.createHash('sha256').update('invoice.dead.v1\n' + JSON.stringify(body), 'utf8').digest('hex');
const dedupe_key = valid_input ? invoice_key : dead_key;
const amount_net_pln = rules && Number.isInteger(quantity) ? rules.unit_net_pln * quantity : 0;
const vat_pln = Math.round(amount_net_pln * VAT_RATE * 100) / 100;
const amount_gross_pln = amount_net_pln + vat_pln;
const yyyymmdd = completed_at.slice(0, 10).replace(/-/g, '');
const invoice_number = 'INV-' + yyyymmdd + '-' + (invoice_key || dead_key).slice(0, 8).toUpperCase();
const next_nudge_due_at = new Date(now.getTime() + FIRST_NUDGE_DAYS * 24 * 60 * 60 * 1000).toISOString();
const ignored_non_completion = !completionLike;
const status = valid_input ? 'Invoice Pending Email' : 'Dead Letter';
const review_reason = valid_input ? '' : errors.join('; ');
const invoice_html = valid_input ? [
  '<section style="font-family:Inter,Arial,sans-serif;color:#111827;line-height:1.45;max-width:760px">',
  '<p style="font-size:12px;color:#6b7280;margin:0 0 16px">CONTROLLED INVOICE TEST - invoice sent to controlled inbox only</p>',
  '<h1 style="font-size:24px;margin:0 0 8px">Acme Automation invoice ' + htmlEscape(invoice_number) + '</h1>',
  '<p style="margin:0 0 18px">Completed job <strong>' + htmlEscape(job_id) + '</strong> for <strong>' + htmlEscape(company) + '</strong> (' + htmlEscape(verified_email) + ')</p>',
  '<table style="width:100%;border-collapse:collapse;margin:16px 0"><thead><tr><th align="left" style="border-bottom:1px solid #d1d5db;padding:8px">Completed service</th><th align="right" style="border-bottom:1px solid #d1d5db;padding:8px">Qty</th><th align="right" style="border-bottom:1px solid #d1d5db;padding:8px">Unit net</th><th align="right" style="border-bottom:1px solid #d1d5db;padding:8px">Subtotal</th></tr></thead><tbody>',
  '<tr><td style="padding:8px;border-bottom:1px solid #e5e7eb">' + htmlEscape(rules.label) + '</td><td align="right" style="padding:8px;border-bottom:1px solid #e5e7eb">' + quantity + '</td><td align="right" style="padding:8px;border-bottom:1px solid #e5e7eb">' + money(rules.unit_net_pln) + ' PLN</td><td align="right" style="padding:8px;border-bottom:1px solid #e5e7eb">' + money(amount_net_pln) + ' PLN</td></tr>',
  '</tbody></table>',
  '<p><strong>Total net:</strong> ' + money(amount_net_pln) + ' PLN<br><strong>VAT 23%:</strong> ' + money(vat_pln) + ' PLN<br><strong>Total gross:</strong> ' + money(amount_gross_pln) + ' PLN</p>',
  '<p><strong>Completed at:</strong> ' + htmlEscape(completed_at) + '<br><strong>Price-book version:</strong> ' + htmlEscape(PRICE_BOOK_VERSION) + '</p>',
  '<p style="font-size:12px;color:#6b7280">Idempotency key: ' + htmlEscape(invoice_key) + '. Amounts are workflow price-book derived only.</p>',
  '</section>',
].join('') : '';
return { json: {
  invoice_key: dedupe_key,
  real_invoice_key: invoice_key,
  onboarding_id,
  smoke_tag,
  dedupe_key,
  invoice_number,
  job_id,
  completion_event_id,
  client_name,
  company,
  verified_email,
  service_code,
  price_book_version: PRICE_BOOK_VERSION,
  currency: 'PLN',
  amount_net_pln,
  vat_pln,
  amount_gross_pln,
  status,
  created_at: now.toISOString(),
  updated_at: now.toISOString(),
  completed_at,
  invoice_email_sent: false,
  invoice_email_id: '',
  invoice_html,
  nudge_count: 0,
  last_nudge_number_sent: 0,
  last_nudge_at: '',
  next_nudge_due_at,
  last_nudge_claim_key: '',
  paid_at: '',
  payment_event_id: '',
  escalated_at: '',
  review_reason,
  last_execution_id: $execution.id,
  raw_event_json: JSON.stringify(body),
  last_error_class: valid_input ? '' : (ignored_non_completion ? 'business' : 'permanent'),
  last_error_message: valid_input ? '' : review_reason,
  valid_input,
  ignored_non_completion,
} };

const pruneStore = (obj, max = 5000) => {
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length - max; i++) delete obj[keys[i]];
};
const n = $input.item.json;
if (!n.valid_input) {
  return { json: { ...n, duplicate_claim: false, duplicate_status: '', existing_record_id: '' } };
}
const claimKey = [n.invoice_key, n.onboarding_id || '', n.smoke_tag || ''].join('\n');
const store = $getWorkflowStaticData('global');
store.invoice_claims = store.invoice_claims || {};
pruneStore(store.invoice_claims);
const claims = store.invoice_claims;
const now = Date.now();
const staleInProgressMs = 15 * 60 * 1000;
const claim = claims[claimKey];
const claimAge = claim?.claimed_at ? now - Date.parse(claim.claimed_at) : 0;
const activeClaim = claim && (claim.status !== 'in_progress' || claimAge < staleInProgressMs);
if (activeClaim) {
  return { json: { ...n, duplicate_claim: true, duplicate_status: claim.status || 'seen', existing_record_id: claim.record_id || '' } };
}
claims[claimKey] = {
  status: 'in_progress',
  claimed_at: new Date(now).toISOString(),
  first_execution_id: n.last_execution_id,
  invoice_number: n.invoice_number,
};
return { json: { ...n, duplicate_claim: false, duplicate_status: '', existing_record_id: '' } };

const pruneStore = (obj, max = 5000) => {
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length - max; i++) delete obj[keys[i]];
};
const n = $('Normalize Completion Event').item.json;
const record = $input.item.json || {};
if (!n.valid_input) return { json: record };
const claimKey = [n.invoice_key, n.onboarding_id || '', n.smoke_tag || ''].join('\n');
const store = $getWorkflowStaticData('global');
store.invoice_claims = store.invoice_claims || {};
pruneStore(store.invoice_claims);
store.invoice_claims[claimKey] = {
  ...(store.invoice_claims[claimKey] || {}),
  status: 'Dead Letter',
  record_id: record.id || '',
  completed_at: new Date().toISOString(),
  first_execution_id: n.last_execution_id,
};
return { json: record };

const inserted = $('Insert Invoice Pending Email').item.json || {};
const email = $('Send Controlled Invoice Email').item.json || {};
return { json: {
  id: inserted.id,
  status: 'Invoice Sent',
  updated_at: new Date().toISOString(),
  invoice_email_sent: true,
  invoice_email_id: email.id || '',
  last_execution_id: $('Normalize Completion Event').item.json.last_execution_id,
} };

const pruneStore = (obj, max = 5000) => {
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length - max; i++) delete obj[keys[i]];
};
const n = $('Normalize Completion Event').item.json;
const record = $input.item.json || {};
const claimKey = [n.invoice_key, n.onboarding_id || '', n.smoke_tag || ''].join('\n');
const inserted = $('Insert Invoice Pending Email').item.json || {};
const email = $('Send Controlled Invoice Email').item.json || {};
const store = $getWorkflowStaticData('global');
store.invoice_claims = store.invoice_claims || {};
pruneStore(store.invoice_claims);
store.invoice_claims[claimKey] = {
  ...(store.invoice_claims[claimKey] || {}),
  status: 'Invoice Sent',
  record_id: record.id || inserted.id || '',
  completed_at: new Date().toISOString(),
  first_execution_id: n.last_execution_id,
  invoice_number: n.invoice_number,
  invoice_email_id: email.id || '',
};
return { json: { ...record, id: record.id || inserted.id || '', invoice_email_id: email.id || '' } };

const root = $input.item.json || {};
const headers = root.headers || {};
const header = (name) => headers[name] || headers[name.toLowerCase()] || headers[name.toUpperCase()] || '';
const rawAuth = String(header('authorization') || '');
const bearer = rawAuth.toLowerCase().startsWith('bearer ') ? rawAuth.slice(7).trim() : '';
const provided = String(header('x-dunning-token') || bearer || '').trim();
const expected = String($vars.DUNNING_WEBHOOK_TOKEN || '').trim();
return { json: {
  ...root,
  auth_ok: Boolean(expected && provided && provided === expected),
  auth_reason: !expected ? 'missing_server_token_var' : !provided ? 'missing_token_header' : provided === expected ? '' : 'bad_token',
  checked_at: new Date().toISOString(),
} };

const crypto = require('crypto');
const root = $input.item.json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const collapse = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const pick = (...keys) => {
  for (const key of keys) {
    const value = body[key];
    if (value !== undefined && value !== null && collapse(value) !== '') return collapse(value);
  }
  return '';
};
const event_type = collapse(pick('event_type', 'type')).toLowerCase();
const payment_event_id = collapse(pick('event_id', 'id', 'payment_event_id')) || crypto.createHash('sha256').update(JSON.stringify(body)).digest('hex').slice(0, 16);
const job_id = collapse(pick('job_id', 'jobId', 'work_order_id'));
const invoice_key = job_id ? crypto.createHash('sha256').update('invoice.v1\n' + job_id, 'utf8').digest('hex') : collapse(pick('invoice_key'));
const hasOwn = (name) => Object.prototype.hasOwnProperty.call(body, name);
const onboarding_id_provided = hasOwn('onboarding_id');
const onboarding_id_value = body.onboarding_id;
const onboarding_id_valid = !onboarding_id_provided || (typeof onboarding_id_value === 'string' && /^[a-f0-9]{64}$/i.test(onboarding_id_value));
const onboarding_id = onboarding_id_valid && onboarding_id_provided ? onboarding_id_value.toLowerCase() : '';
const smoke_tag_provided = hasOwn('smoke_tag');
const smoke_tag_value = body.smoke_tag;
const smoke_tag_valid = !smoke_tag_provided || (typeof smoke_tag_value === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(smoke_tag_value));
const smoke_tag = smoke_tag_valid && smoke_tag_provided ? smoke_tag_value : '';
const paidAtRaw = collapse(pick('paid_at', 'paidAt', 'payment_time')) || new Date().toISOString();
const paidDate = new Date(paidAtRaw);
const paid_at = Number.isNaN(paidDate.getTime()) ? new Date().toISOString() : paidDate.toISOString();
const valid_input = ['invoice.paid', 'payment.succeeded', 'paid'].includes(event_type) && !!invoice_key && onboarding_id_valid && smoke_tag_valid;
return { json: {
  event_type,
  payment_event_id,
  job_id,
  invoice_key,
  onboarding_id,
  smoke_tag,
  onboarding_id_provided,
  smoke_tag_provided,
  scope_explicit: onboarding_id_provided || smoke_tag_provided,
  paid_at,
  valid_input,
  review_reason: valid_input ? '' : 'invalid payment payload: event type, invoice identity, onboarding_id, or smoke_tag is invalid',
  last_execution_id: $execution.id,
  raw_event_json: JSON.stringify(body),
} };

const pruneStore = (obj, max = 5000) => {
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length - max; i++) delete obj[keys[i]];
};
const n = $input.item.json;
const store = $getWorkflowStaticData('global');
store.payment_claims = store.payment_claims || {};
pruneStore(store.payment_claims);
const scopedInvoiceKey = n.onboarding_id || n.smoke_tag
  ? [n.invoice_key, 'scope', n.onboarding_id || '', n.smoke_tag || ''].join(':')
  : n.invoice_key;
const key = scopedInvoiceKey + ':paid:' + n.payment_event_id;
const claims = store.payment_claims;
const now = Date.now();
const claim = claims[key];
const claimAge = claim?.claimed_at ? now - Date.parse(claim.claimed_at) : 0;
const activeClaim = claim && (claim.status !== 'in_progress' || claimAge < 15 * 60 * 1000);
if (activeClaim) return { json: { ...n, payment_duplicate_claim: true, payment_claim_key: key, duplicate_status: claim.status || 'seen' } };
claims[key] = { status: 'in_progress', claimed_at: new Date(now).toISOString(), first_execution_id: n.last_execution_id };
return { json: { ...n, payment_duplicate_claim: false, payment_claim_key: key, duplicate_status: '' } };

const row = $input.item.json || {};
const p = $('Normalize Payment Event').item.json;
return { json: {
  id: row.id,
  onboarding_id: row.onboarding_id || '',
  smoke_tag: row.smoke_tag || '',
  status: 'Paid',
  updated_at: new Date().toISOString(),
  paid_at: p.paid_at,
  payment_event_id: p.payment_event_id,
  review_reason: 'Paid event received; dunning stops immediately',
  last_execution_id: p.last_execution_id,
} };

const pruneStore = (obj, max = 5000) => {
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length - max; i++) delete obj[keys[i]];
};
const p = $('Claim Payment Event').item.json;
const store = $getWorkflowStaticData('global');
store.payment_claims = store.payment_claims || {};
pruneStore(store.payment_claims);
store.payment_claims[p.payment_claim_key] = {
  ...(store.payment_claims[p.payment_claim_key] || {}),
  status: 'Paid',
  completed_at: new Date().toISOString(),
  first_execution_id: p.last_execution_id,
};
return { json: $input.item.json };

const now = Date.now();
const MS_DAY = 24 * 60 * 60 * 1000;
const MAX_NUDGES = 3;
const ESCALATE_AFTER_DAYS = 21;
const HIGH_VALUE_GROSS_PLN = 15000;
const HIGH_VALUE_ESCALATE_AFTER_DAYS = 14;
const rows = $input.all().map(item => item.json || {});
return rows.flatMap(row => {
  if (!row.id || row.status !== 'Invoice Sent' || row.paid_at) return [];
  const dueAt = Date.parse(row.next_nudge_due_at || row.created_at || row.createdAt || '');
  if (!Number.isFinite(dueAt) || dueAt > now) return [];
  const basis = Date.parse(row.completed_at || row.created_at || row.createdAt || row.updatedAt || '') || now;
  const ageDays = Math.floor((now - basis) / MS_DAY);
  const nudgeCount = Number(row.nudge_count || 0);
  const gross = Number(row.amount_gross_pln || 0);
  const highValueStuck = gross >= HIGH_VALUE_GROSS_PLN && ageDays >= HIGH_VALUE_ESCALATE_AFTER_DAYS;
  const maxNudgesStuck = nudgeCount >= MAX_NUDGES && ageDays >= ESCALATE_AFTER_DAYS;
  if (highValueStuck || maxNudgesStuck || nudgeCount >= MAX_NUDGES) return [];
  const action = 'nudge';
  const nextNudgeNumber = nudgeCount + 1;
const actionScope = row.onboarding_id || row.smoke_tag
    ? ['scope', row.onboarding_id || '', row.smoke_tag || '']
    : [];
  const actionKey = [
    row.invoice_key,
    ...actionScope,
    action,
    action === 'nudge' ? nextNudgeNumber : 'human',
  ].join(':');
  return [{ json: {
    ...row,
    action,
    action_key: actionKey,
    next_nudge_number: nextNudgeNumber,
    age_days: ageDays,
    high_value_stuck: highValueStuck,
    max_nudges_stuck: maxNudgesStuck,
    last_execution_id: $execution.id,
  } }];
});

const pruneStore = (obj, max = 5000) => {
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length - max; i++) delete obj[keys[i]];
};
const store = $getWorkflowStaticData('global');
store.dunning_claims = store.dunning_claims || {};
pruneStore(store.dunning_claims);
const claims = store.dunning_claims;
const now = Date.now();
return $input.all().flatMap(item => {
const row = item.json || {};
const store = $getWorkflowStaticData('global');
const claim = claims[row.action_key];
const claimAge = claim?.claimed_at ? now - Date.parse(claim.claimed_at) : 0;
const activeClaim = claim && (claim.status !== 'in_progress' || claimAge < 15 * 60 * 1000);
if (activeClaim) return [];
claims[row.action_key] = { status: 'in_progress', claimed_at: new Date(now).toISOString(), first_execution_id: row.last_execution_id };
return [{ json: { ...row, dunning_duplicate_claim: false, duplicate_status: '' } }];
});

const plannedItems = $('Claim Dunning Action').all();
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}[ch]));

// Stop logic is implicit: returning no item means no claim update, Gmail send, or sent-state update.
return $input.all().flatMap((item, index) => {
  const planned = (plannedItems[index] || {}).json || {};
  const row = item.json || {};
  if (!row.id) return [];
  if (row.status === 'Paid' || row.paid_at) return [];
  if (row.status === 'Escalated') return [];
  if (planned.action === 'nudge' && Number(row.nudge_count || 0) >= Number(planned.next_nudge_number || 0)) {
    return [];
  }
  return [{ json: {
    ...planned,
    ...row,
    expected_status: row.status,
    expected_claim_key: String(row.last_nudge_claim_key || ''),
    invoice_number_html: esc(row.invoice_number || planned.invoice_number),
    company_html: esc(row.company || planned.company),
    verified_email_html: esc(row.verified_email || planned.verified_email),
    stop_chase: false,
    stop_reason: '',
  } }];
});

const row = $input.item.json;
return { json: {
  ...row,
  status: row.expected_status,
  updated_at: new Date().toISOString(),
  last_nudge_claim_key: row.action_key,
  review_reason: 'Nudge ' + row.next_nudge_number + ' claimed by action key before controlled send',
  last_execution_id: row.last_execution_id || $execution.id,
} };

const row = $('Build Dunning Recheck Decision').item.json;
const now = new Date();
const n = Number(row.next_nudge_number || 1);
const delayDays = n === 1 ? 4 : n === 2 ? 7 : 7;
return { json: {
  id: row.id,
  expected_status: row.expected_status,
  status: 'Invoice Sent',
  updated_at: now.toISOString(),
  nudge_count: n,
  last_nudge_number_sent: n,
  last_nudge_at: now.toISOString(),
  next_nudge_due_at: new Date(now.getTime() + delayDays * 24 * 60 * 60 * 1000).toISOString(),
  last_nudge_claim_key: row.action_key,
  review_reason: 'Controlled dunning nudge ' + n + ' sent; replay key ' + row.action_key,
  last_execution_id: row.last_execution_id || $execution.id,
} };

const pruneStore = (obj, max = 5000) => {
  const keys = Object.keys(obj);
