const now = Date.now();
const MS_DAY = 24 * 60 * 60 * 1000;
const MAX_NUDGES = 3;
const ESCALATE_AFTER_DAYS = 21;
const HIGH_VALUE_GROSS_PLN = 15000;
const HIGH_VALUE_ESCALATE_AFTER_DAYS = 14;
return $input.all().flatMap(item => {
  const row = item.json || {};
  if (!row.id || row.status !== 'Invoice Sent' || row.paid_at) return [];
  const basis = Date.parse(row.completed_at || row.created_at || row.createdAt || row.updatedAt || '') || now;
  const ageDays = Math.floor((now - basis) / MS_DAY);
  const nudgeCount = Number(row.nudge_count || 0);
  const gross = Number(row.amount_gross_pln || 0);
  const highValueStuck = gross >= HIGH_VALUE_GROSS_PLN && ageDays >= HIGH_VALUE_ESCALATE_AFTER_DAYS;
  const maxNudgesStuck = nudgeCount >= MAX_NUDGES && ageDays >= ESCALATE_AFTER_DAYS;
  if (!highValueStuck && !maxNudgesStuck) return [];
  return [{ json: {
    ...row,
    action: 'escalate',
    action_key: [row.invoice_key, ...(row.onboarding_id || row.smoke_tag ? ['scope', row.onboarding_id || '', row.smoke_tag || ''] : []), 'escalate', 'human'].join(':'),
    age_days: ageDays,
    high_value_stuck: highValueStuck,
    max_nudges_stuck: maxNudgesStuck,
    last_execution_id: $execution.id,
  } }];
});

